import os
import json
import subprocess
from flask import Flask, request, jsonify, send_file
from werkzeug.utils import secure_filename
import tempfile
import shlex

app = Flask(__name__)

UPLOAD_DIR = '/var/lib/reports/uploads'
OUTPUT_DIR = '/var/lib/reports/output'
ALLOWED_EXTENSIONS = {'csv', 'json', 'xml'}

def allowed_file(filename):
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

def sanitize_title(title):
    # Remove obvious shell metacharacters but allow spaces and hyphens
    blocked = ['`', '$', '|', '>', '<', '&', ';', '\\', '\n', '\r']
    for ch in blocked:
        title = title.replace(ch, '')
    return title

@app.route('/api/v2/reports/generate', methods=['POST'])
def generate_report():
    """Generate PDF report from uploaded data with custom title."""
    if 'datafile' not in request.files:
        return jsonify({'error': 'No data file provided'}), 400

    datafile = request.files['datafile']
    if not allowed_file(datafile.filename):
        return jsonify({'error': 'Invalid file type'}), 400

    report_title = request.form.get('title', 'Untitled Report')
    report_format = request.form.get('format', 'pdf')
    template_name = request.form.get('template', 'default')

    # Sanitize inputs
    safe_filename = secure_filename(datafile.filename)
    report_title = sanitize_title(report_title)

    if len(report_title) > 200:
        return jsonify({'error': 'Title too long'}), 400

    if template_name not in ['default', 'executive', 'detailed', 'summary']:
        return jsonify({'error': 'Invalid template'}), 400

    # Save uploaded file
    upload_path = os.path.join(UPLOAD_DIR, safe_filename)
    datafile.save(upload_path)

    # Generate output filename
    output_name = f"report_{os.urandom(8).hex()}.{report_format}"
    output_path = os.path.join(OUTPUT_DIR, output_name)

    # Build wkhtmltopdf command with title metadata
    # The title is embedded in the command for PDF metadata
    cmd = f'wkhtmltopdf --title "{report_title}" --header-center "{report_title}" '\
          f'--template /opt/report-templates/{template_name}.html '\
          f'--data-file {upload_path} {output_path}'

    try:
        result = subprocess.run(
            cmd,
            shell=True,
            timeout=30,
            capture_output=True,
            cwd=OUTPUT_DIR
        )
        if result.returncode != 0:
            return jsonify({'error': 'Report generation failed', 
                          'details': result.stderr.decode()[:500]}), 500
    except subprocess.TimeoutExpired:
        return jsonify({'error': 'Report generation timed out'}), 504

    return jsonify({
        'status': 'success',
        'report_url': f'/api/v2/reports/download/{output_name}'
    })

@app.route('/api/v2/reports/download/<filename>')
def download_report(filename):
    safe = secure_filename(filename)
    filepath = os.path.join(OUTPUT_DIR, safe)
    if not os.path.exists(filepath):
        return jsonify({'error': 'Report not found'}), 404
    return send_file(filepath, as_attachment=True)

@app.route('/api/v2/reports/templates', methods=['GET'])
def list_templates():
    return jsonify({'templates': ['default', 'executive', 'detailed', 'summary']})

@app.route('/health')
def health():
    return jsonify({'status': 'ok', 'version': '2.4.1'})

if __name__ == '__main__':
    os.makedirs(UPLOAD_DIR, exist_ok=True)
    os.makedirs(OUTPUT_DIR, exist_ok=True)
    app.run(host='0.0.0.0', port=8080)
